meta.script:
(function() {
  try {
    var t = localStorage.getItem('vp_theme');
    if (t === 'dark') {
      document.documentElement.classList.add('dark');
    }
  } catch(e) {}
})();

div.pre:
const res = await fetch("https://api.vipvap.xyz/v1/send", {
  method: "POST",
  headers: {
    "Authorization": `Bearer ${process.env.VIPVAP_KEY}`,
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    recipient:  "alice@acme.com",
    code:       "418917",
  }),
});

const data = await res.json();
console.log(data.status); // "delivered"
